    if (scene.audioSfx.length > 0)
        lines.push(`[SOUNDS] ${scene.audioSfx.join(', ')}`);
    if (scene.music)
        lines.push(`[MUSIC] ${scene.music}`);
    if (scene.dialogue)
        lines.push(`[SPEECH] ${scene.dialogue}`);
    lines.push(`Reference: ${referenceTag} (use as keyframe identity).`);
