        errors.push('missing COUNT / GRID CONTRACT section');
    if (!/REFERENCE IMAGES:/i.test(prompt))
        errors.push('missing REFERENCE IMAGES section');
    if (!/CANVAS \/ LAYOUT:/i.test(prompt))
        errors.push('missing CANVAS / LAYOUT section');
